    TRAIN_CACHE = os.path.join(WORKING_DIR, "train_data_ds_pfn_v1.npz")
    VAL_CACHE = os.path.join(WORKING_DIR, "val_data_ds_pfn_v1.npz")
    TEST_CACHE = os.path.join(WORKING_DIR, "test_data_ds_pfn_v1.npz")

    # Output Paths
    BEST_MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_PATH = os.path.join(WORKING_DIR, "submission.csv")

    # =========================================================================
    # Data Specifications
    # =========================================================================
    SEQ_LEN = 107
    SEQ_SCORED = 68

    # Target Columns in the order they appear in the dataset/metadata
    TARGET_COLS = ["reactivity", "deg_Mg_pH10", "deg_pH10", "deg_Mg_50C", "deg_50C"]

    # Columns used for the competition metric
    SCORED_COLS = ["reactivity", "deg_Mg_pH10", "deg_Mg_50C"]

    # Indices of the scored columns within the full TARGET_COLS list
    # reactivity (0), deg_Mg_pH10 (1), deg_pH10 (2), deg_Mg_50C (3), deg_50C (4)
    SCORED_INDICES = [0, 1, 3]

    # Vocabulary Mappings for One-Hot Encoding
    TOKEN_TO_INT_SEQ = {"A": 0, "G": 1, "U": 2, "C": 3}
    TOKEN_TO_INT_STRUCT = {".": 0, "(": 1, ")": 2}
    TOKEN_TO_INT_LOOP = {"S": 0, "M": 1, "I": 2, "B": 3, "H": 4, "E": 5, "X": 6}

    # Feature Dimensions (Channels)
    VOCAB_SIZE_SEQ = 4
    VOCAB_SIZE_STRUCT = 3
    VOCAB_SIZE_LOOP = 7
    VOCAB_SIZE_PARTNER = 4  # Partner Identity (A, G, U, C)

    # Total Input Channels = 4 (Seq) + 3 (Struct) + 7 (Loop) + 4 (Partner)
    INPUT_CHANNELS = 18

