    # =========================================================================
    # Decoupled Input Stem
    STEM_KERNEL_SIZE = 1

    # Pre-Activation Dense Dilated Backbone
    BACKBONE_GROWTH_RATE = 64
    BACKBONE_LAYERS = 6
