    BACKBONE_KERNEL_SIZE = 3
    BACKBONE_DROPOUT = 0.1
    LATENT_DIM = 64  # Z dimension

    # Pure-Feedback Module
    FEEDBACK_INPUT_CHANNELS = 5  # Number of target columns
