    FEEDBACK_EMBED_DIM = 32  # E_fb dimension
    FEEDBACK_KERNEL_SIZE = 3
    FEEDBACK_DILATIONS = [1, 2, 4, 8, 16, 32]

    # Interaction & Aggregation (RNN)
    RNN_HIDDEN_SIZE = 64  # Compact size constraint
    RNN_LAYERS = 1
